// Runs the control plane's validation cases against the Web UI's port of
// its rules. validation-parity.json holds what the Go rules return for each
// input; it is generated by the Go test TestWebParityFixture
// (internal/controlplane/webapi/parity_test.go), which fails whenever the
// rules change until it is regenerated.

import { describe, expect, it } from "vitest"

import fixture from "./validation-parity.json"
import { baseUrlProblem, envNameProblem, keyProblem } from "./provider-rules"
import {
  checkIdentityName,
  checkPath,
  checkProjectName,
  checkRepoUrl,
  normalizePath,
  sameProjectName,
  type Checked,
} from "./validation"

type Fn = "checkName" | "checkIdentityName" | "checkPath" | "checkRepoURL" | "normalizePath" | "sameProjectName"

interface Case {
  fn: Fn
  args: string[]
  result: string
  /** Empty when accepted; absent for normalizePath and sameProjectName. */
  problem?: string
}

const cases = fixture.cases as Case[]

/** What the Go function returned, in the shape of the TypeScript one. */
const expected = (c: Case): Checked | string | boolean => {
  if (c.fn === "sameProjectName") return c.result === "true"
  if (c.problem === undefined) return c.result
  return c.problem === "" ? { ok: true, value: c.result } : { ok: false, problem: expect.any(String) as unknown as string }
}

const run: Record<Fn, (args: string[]) => Checked | string | boolean> = {
  checkName: ([raw]) => checkProjectName(raw),
  checkIdentityName: ([raw]) => checkIdentityName(raw),
  checkPath: ([raw, os]) => checkPath(raw, os),
  checkRepoURL: ([raw]) => checkRepoUrl(raw),
  normalizePath: ([path, os]) => normalizePath(path, os),
  sameProjectName: ([a, b]) => sameProjectName(a, b),
}

const label = (c: Case) =>
  `${c.fn}(${c.args.map((a) => JSON.stringify(a.length > 60 ? `${a.slice(0, 60)}…` : a)).join(", ")})`

/** Accepted and refused cases of a validator, or true and false ones of a comparison. */
const outcomes = (fn: Fn) => {
  const of = cases.filter((c) => c.fn === fn)
  const yes = of.filter((c) => (c.problem === undefined ? c.result === "true" : c.problem === "")).length
  return { yes, no: of.length - yes, all: of.length }
}

describe("validation parity with the control plane", () => {
  it("covers both outcomes of every validator", () => {
    for (const fn of ["checkName", "checkIdentityName", "checkPath", "checkRepoURL"] as const) {
      const { yes, no } = outcomes(fn)
      expect.soft(yes, `${fn} accepted`).toBeGreaterThanOrEqual(15)
      expect.soft(no, `${fn} refused`).toBeGreaterThanOrEqual(15)
    }
    expect(outcomes("normalizePath").all).toBeGreaterThanOrEqual(30)
    const fold = outcomes("sameProjectName")
    expect(fold.yes).toBeGreaterThanOrEqual(10)
    expect(fold.no).toBeGreaterThanOrEqual(5)
  })

  it("agrees on every case", () => {
    const mismatches = cases
      .filter((c) => {
        try {
          expect(run[c.fn](c.args)).toEqual(expected(c))
          return false
        } catch {
          return true
        }
      })
      .map((c) => `${label(c)}: Go ${c.problem ? "refuses" : JSON.stringify(c.result)}, Web ${JSON.stringify(run[c.fn](c.args))}`)
    expect(mismatches).toEqual([])
  })
})

type ProviderFn = "checkBaseURL" | "checkProviderKey" | "checkEnvName"

interface ProviderCase {
  fn: ProviderFn
  args: [string]
  result: string
  /** Empty when the server accepts the input. */
  problem: string
}

const providerCases = fixture.providerCases as ProviderCase[]

/** Whether the Web's rule accepts the input (the server's form rules, ported in provider-rules.ts). */
const accepts: Record<ProviderFn, (raw: string) => boolean> = {
  checkBaseURL: (raw) => baseUrlProblem(raw) === null,
  // The server checks a key it was sent; an empty one means "keep" there.
  checkProviderKey: (raw) => keyProblem(raw, true) === null,
  checkEnvName: (raw) => envNameProblem(raw) === null,
}

describe("provider rules' parity with the control plane", () => {
  it("covers both outcomes of every rule", () => {
    for (const fn of ["checkBaseURL", "checkProviderKey", "checkEnvName"] as const) {
      const of = providerCases.filter((c) => c.fn === fn)
      expect.soft(of.filter((c) => c.problem === "").length, `${fn} accepted`).toBeGreaterThanOrEqual(2)
      expect.soft(of.filter((c) => c.problem !== "").length, `${fn} refused`).toBeGreaterThanOrEqual(5)
    }
  })

  it("agrees on every case", () => {
    const mismatches = providerCases
      .filter((c) => accepts[c.fn](c.args[0]) !== (c.problem === ""))
      .map((c) => `${c.fn}(${JSON.stringify(c.args[0].length > 60 ? `${c.args[0].slice(0, 60)}…` : c.args[0])}): Go ${c.problem === "" ? "accepts" : "refuses"}`)
    expect(mismatches).toEqual([])
  })
})
